/* Animated.Value stores the current value of animation */
import React, { useRef, useEffect } from 'react';
import { Animated, View, Button } from 'react-native';

export default function FadeInExample() {
  const fadeAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 2000,
      useNativeDriver: true,
    }).start();
  }, [fadeAnim]);

  return (
    <Animated.View style={{ opacity: fadeAnim, width: 100, height: 100, backgroundColor: 'blue' }} />
  );
}

Animated supports animating properties like opacity, position, scale, rotation.

Example: Move and scale a box

```js
const moveAnim = useRef(new Animated.Value(0)).current;

Animated.timing(moveAnim, {
  toValue: 100,
  duration: 1000,
  useNativeDriver: true
}).start();

return (
  <Animated.View
    style={{
      transform: [
        { translateX: moveAnim },
        { scale: moveAnim.interpolate({
            inputRange: [0, 100],
            outputRange: [1, 2]
          })
        }
      ]
    }}
  />
)
```

import React, { useRef, useEffect } from 'react';
import { Animated, View, Text } from 'react-native';

export default function FadeSlideExample() {
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(50)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: 1000,
        useNativeDriver: true,
      }),
      Animated.timing(slideAnim, {
        toValue: 0,
        duration: 1000,
        useNativeDriver: true,
      }),
    ]).start();
  }, []);

  return (
    <Animated.View style={{
      opacity: fadeAnim,
      transform: [{ translateY: slideAnim }],
      backgroundColor: 'tomato',
      padding: 20,
      borderRadius: 10
    }}>
      <Text style={{ color: 'white' }}>Hello Animations!</Text>
    </Animated.View>
  );
}
